// Generates the index of shared code inside AGENTS.md. Zero dependencies:
// `dart run scripts/agent_index.dart` writes the managed block,
// `dart run scripts/agent_index.dart --check` fails when it is stale, when an
// indexed public declaration has no doc sentence, or when the block is too big.
//
// Indexed: packages/*/lib of app_ui and app_shared, and
// apps/*/lib/features/*/application. Generated files and l10n are skipped.
import 'dart:io';

const beginMarker = '<!-- BEGIN:agent-index -->';
const endMarker = '<!-- END:agent-index -->';
const maxBlockChars = 8000;

const _intro =
    'Generated by `make index` from the first sentence of each declaration\'s '
    'doc comment; do not edit by hand. Before writing a widget, helper or use '
    'case, find it here and read its file; a UI package index in this file '
    'comes before `app_ui`. If nothing fits, say what you looked for, then add '
    'it to the right package with a one-sentence doc comment.';

final _classLike = RegExp(
  r'^(?:(?:abstract|sealed|final|base|interface|mixin)\s+)*'
  r'(?:class|mixin|enum)\s+(\w+)',
);
final _extension = RegExp(r'^extension\s+(\w+)\s+on\b');
final _typedef = RegExp(r'^typedef\s+(\w+)');
final _variable = RegExp(r'^(?:const|final)\s+(?:[^=(]*?\s)?(\w+)\s*=');
final _function = RegExp(
  r'^[\w<>?,.\[\]]+(?: [\w<>?,.\[\]]+)*? (\w+)(?:<[^>]*>)?\(',
);
const _notDeclarations = {
  'import',
  'export',
  'part',
  'library',
  'return',
  'if',
  'for',
  'while',
  'switch',
};

/// A public top-level declaration. [doc] is empty when it has no doc sentence.
class Decl {
  const Decl(this.name, this.line, this.doc);

  final String name;
  final int line;
  final String doc;
}

String? _nameOf(String line) {
  if (line.isEmpty || line.startsWith(RegExp(r'[\s@}/)\]]'))) return null;
  if (_notDeclarations.contains(line.split(RegExp(r'\W')).first)) return null;
  return (_classLike.firstMatch(line) ??
          _extension.firstMatch(line) ??
          _typedef.firstMatch(line) ??
          _variable.firstMatch(line) ??
          _function.firstMatch(line))
      ?.group(1);
}

/// First sentence of [text]: up to the first `. ` or the end, whitespace
/// collapsed.
String firstSentence(String text) {
  final flat = text.replaceAll(RegExp(r'\s+'), ' ').trim();
  final end = flat.indexOf('. ');
  return end < 0 ? flat : flat.substring(0, end + 1);
}

/// Public top-level declarations of [source] in source order.
List<Decl> declarations(String source) {
  final lines = source.split('\n');
  final out = <Decl>[];
  for (var i = 0; i < lines.length; i++) {
    final name = _nameOf(lines[i]);
    if (name == null || name.startsWith('_')) continue;
    var j = i - 1;
    while (j >= 0 && lines[j].startsWith('@')) {
      j--;
    }
    final doc = <String>[];
    while (j >= 0 && lines[j].trimLeft().startsWith('///')) {
      doc.insert(0, lines[j].trimLeft().substring(3));
      j--;
    }
    out.add(Decl(name, i + 1, firstSentence(doc.join(' '))));
  }
  return out;
}

/// `name: sentence` per declaration, joined by single spaces. Consecutive
/// names with the same sentence are listed once as `A, B: sentence`.
String indexLine(String importPath, List<Decl> decls) {
  final groups = <(List<String>, String)>[];
  for (final d in decls) {
    if (groups.isNotEmpty && groups.last.$2 == d.doc && d.doc.isNotEmpty) {
      groups.last.$1.add(d.name);
    } else {
      groups.add(([d.name], d.doc));
    }
  }
  return '$importPath|${groups.map((g) => '${g.$1.join(', ')}: ${g.$2}').join(' ')}';
}

/// The managed block, markers included.
String renderBlock(List<String> lines) => [
  beginMarker,
  '## Index of shared code',
  '',
  _intro,
  '',
  '```text',
  ...lines,
  '```',
  endMarker,
].join('\n');

/// [agents] with its managed block replaced by [block]; a missing block is
/// inserted before the `## Rules` heading (after the structure section).
String applyBlock(String agents, String block) {
  final begin = agents.indexOf(beginMarker);
  final end = agents.indexOf(endMarker);
  if (begin >= 0 && end > begin) {
    return agents.replaceRange(begin, end + endMarker.length, block);
  }
  final rules = agents.indexOf('\n## Rules');
  if (rules < 0) return '${agents.trimRight()}\n\n$block\n';
  return '${agents.substring(0, rules + 1)}$block\n${agents.substring(rules)}';
}

/// The block currently in [agents], or null.
String? currentBlock(String agents) {
  final begin = agents.indexOf(beginMarker);
  final end = agents.indexOf(endMarker);
  return begin >= 0 && end > begin
      ? agents.substring(begin, end + endMarker.length)
      : null;
}

String _packageName(String dir) {
  final m = RegExp(
    r'^name:\s*(\S+)',
    multiLine: true,
  ).firstMatch(File('$dir/pubspec.yaml').readAsStringSync());
  return m!.group(1)!;
}

/// Repo-relative paths of the indexed files, sorted.
List<String> indexedFiles() {
  bool wanted(String p) =>
      p.endsWith('.dart') &&
      !p.endsWith('.g.dart') &&
      !p.endsWith('.freezed.dart') &&
      !p.contains('/lib/l10n/');
  final files = <String>[];
  for (final pkg in ['app_ui', 'app_shared']) {
    final lib = Directory('packages/$pkg/lib');
    if (lib.existsSync()) {
      files.addAll(lib.listSync(recursive: true).map((e) => e.path));
    }
  }
  final apps = Directory('apps');
  if (apps.existsSync()) {
    for (final app in apps.listSync().whereType<Directory>()) {
      final features = Directory('${app.path}/lib/features');
      if (!features.existsSync()) continue;
      files.addAll(
        features
            .listSync(recursive: true)
            .map((e) => e.path)
            .where((p) => p.contains('/application/')),
      );
    }
  }
  return files.where(wanted).toList()..sort();
}

void main(List<String> args) {
  final lines = <String>[];
  final problems = <String>[];
  for (final path in indexedFiles()) {
    final decls = declarations(File(path).readAsStringSync());
    if (decls.isEmpty) continue;
    for (final d in decls.where((d) => d.doc.isEmpty)) {
      problems.add('$path:${d.line} ${d.name}: add a /// doc comment');
    }
    final parts = path.split('/');
    final importPath = parts[0] == 'packages'
        ? 'package:${_packageName('packages/${parts[1]}')}/'
              '${parts.sublist(3).join('/')}'
        : path;
    lines.add(indexLine(importPath, decls));
  }
  final block = renderBlock(lines);
  final file = File('AGENTS.md');
  final agents = file.readAsStringSync();
  if (args.contains('--check')) {
    if (currentBlock(agents) != block) {
      problems.add(
        'AGENTS.md: the agent-index block is stale; run `make index`',
      );
    }
    if (block.length > maxBlockChars) {
      problems.add(
        'AGENTS.md: the agent-index block has ${block.length} characters, '
        'more than $maxBlockChars; shorten doc sentences',
      );
    }
    if (problems.isNotEmpty) {
      stderr.writeln('Agent index problems:');
      problems.forEach(stderr.writeln);
      exit(1);
    }
    stdout.writeln('Agent index OK (${block.length} characters)');
    return;
  }
  file.writeAsStringSync(applyBlock(agents, block));
  problems.forEach(stderr.writeln);
  stdout.writeln('Wrote agent index (${block.length} characters)');
}
